import list

LinkedList = list.LinkedList


def test(list, size, value, contains, notContains):
    assert list.size() == size
    assert list.asList() == value
    for i in range(len(contains)):
      assert list.contains(contains[i]) == True
    for i in range(len(notContains)):
      assert list.contains(notContains[i]) == False
      
test(LinkedList(), 0, [], [], [1,2,3])
test(LinkedList().add(1), 1, [1], [1], [2,3])
test(LinkedList().add(2), 1, [2], [2], [1,3])
test(LinkedList().add(3), 1, [3], [3], [1,2])
test(LinkedList().remove(2), 0, [], [], [1,2,3])
test(LinkedList().add(2).remove(2), 0, [],  [], [1,2,3])
test(LinkedList().add(2).remove(1), 1, [2], [2], [1,3])
test(LinkedList().add(2).remove(1).add(1), 2, [2, 1], [1,2], [3])
